'use client';
import { useEffect,useRef,useState } from 'react';
import Script from 'next/script';
import { ArrowUpRight,CheckCircle2,LoaderCircle } from 'lucide-react';
import { trackEvent } from './analytics';
import type {BookingRequest} from '@/lib/booking';
declare global {interface Window {turnstile?:{render:(element:HTMLElement,options:Record<string,unknown>)=>string;reset:(id:string)=>void;remove:(id:string)=>void};}}
const options=['Website design & development','Website management','SEO & local search','Google Ads','Meta Ads','Social media management','Content & creative','Thumbnail design','AI Search Optimization','Google Local Services Ads','Microsoft Ads Management','LinkedIn Ads Management','Email Marketing','Reputation Management','Conversion Rate Optimization','Lead Generation','Digital Media Buying','Franchise & Multi-Location Marketing','AI Workflow & Automation','Foundation plan','Growth plan','Full Studio plan','Not sure yet'];
export function InquiryForm({booking,initialService=''}:{booking?:BookingRequest;initialService?:string}={}){
  const[status,setStatus]=useState<'idle'|'sending'|'success'|'error'>('idle');const[error,setError]=useState('');const[token,setToken]=useState('');const[refId,setRefId]=useState('');const[preferred,setPreferred]=useState('');
  const widget=useRef<HTMLDivElement>(null);const widgetId=useRef<string|null>(null);const requestId=useRef<string>('');const formRef=useRef<HTMLFormElement>(null);const key=process.env.NEXT_PUBLIC_TURNSTILE_SITE_KEY;
  useEffect(()=>{requestId.current=crypto.randomUUID();const q=initialService||new URLSearchParams(window.location.search).get('service');if(q&&q.length<=100)setPreferred(q);return()=>{if(widgetId.current)window.turnstile?.remove(widgetId.current)}},[initialService]);
  function mountWidget(){if(widget.current&&window.turnstile&&!widgetId.current)widgetId.current=window.turnstile.render(widget.current,{sitekey:key,action:'inquiry',theme:'light',callback:(value:string)=>setToken(value),'expired-callback':()=>setToken(''),'error-callback':()=>{setToken('');setError('The security check could not load. You can also email info@wonderwebstudio.com.')}});}
  async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();if(status==='sending')return;setError('');const data=new FormData(event.currentTarget);if(key&&!token){setError('Please complete the security check.');return}setStatus('sending');
    const params=new URLSearchParams(window.location.search);const utm:Record<string,string>={};['utm_source','utm_medium','utm_campaign'].forEach(k=>{const v=params.get(k);if(v)utm[k]=v.slice(0,120)});
    const body={name:data.get('name'),email:data.get('email'),website:data.get('website'),service:data.get('service'),budget:data.get('budget'),message:data.get('message'),consent:data.get('consent')==='on',companyFax:data.get('companyFax'),token,booking,requestId:requestId.current,source:window.location.pathname,utm};
    try{const response=await fetch('/api/inquiry/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(55000)});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.message||'We could not confirm delivery. Please email info@wonderwebstudio.com.');setRefId(result.reference);setStatus('success');trackEvent('generate_lead',{service:String(body.service),method:booking?'call_request':'website_form'});formRef.current?.reset();}
    catch(e){setStatus('error');setError(e instanceof Error?e.message:'We could not confirm delivery. Please try again or email us.');if(widgetId.current)window.turnstile?.reset(widgetId.current);setToken('');}
  }
  if(status==='success')return <div className="form-success" role="status"><CheckCircle2 size={42}/><h2>{booking?'Thanks. We’ll confirm your call by email.':'Thanks. Let’s make something happen.'}</h2><p>{booking?'Your preferred-time request was accepted by our email service. The call is not booked yet. We’ll check the time and reply with confirmation or an alternative.':'Your inquiry was accepted by our email service. We’ll review your goals and reply to the email address you provided.'}</p><small>Reference: {refId.slice(0,8)}</small><button className="button" onClick={()=>{requestId.current=crypto.randomUUID();widgetId.current=null;setToken('');setStatus('idle')}}>{booking?'Send another request':'Send another inquiry'}<ArrowUpRight size={18}/></button></div>;
  return <form className="inquiry-form" ref={formRef} onSubmit={submit}><div className="form-row"><label>Your name<input name="name" autoComplete="name" required minLength={2} maxLength={100} placeholder="Alex Morgan"/></label><label>Email address<input name="email" autoComplete="email" type="email" required maxLength={254} placeholder="alex@yourbusiness.com"/></label></div><label>Business website (optional)<input name="website" autoComplete="url" maxLength={300} placeholder="yourbusiness.com"/></label><div className="form-row"><label>What can we help with?<select aria-label="What can we help with?" name="service" required value={preferred} onChange={e=>setPreferred(e.target.value)}><option value="" disabled>Select a service</option>{[...options,...(preferred&&!options.includes(preferred)?[preferred]:[])].map(x=><option key={x}>{x}</option>)}</select></label><label>Budget range (optional)<select aria-label="Budget range (optional)" name="budget" defaultValue=""><option value="">Let’s discuss</option><option>Under $1,000 / month</option><option>$1,000–$2,500 / month</option><option>$2,500–$5,000 / month</option><option>$5,000+ / month</option><option>One-time website project</option></select></label></div><label>A little about your project<textarea name="message" required minLength={15} maxLength={4000} rows={5} placeholder="Tell us about your business, your goals, and what you’d like to improve."/></label><div className="honeypot" aria-hidden="true"><label>Company fax<input name="companyFax" tabIndex={-1} autoComplete="off"/></label></div><label className="consent"><input type="checkbox" name="consent" required/><span>I agree to be contacted about this inquiry and have read the <a href="/privacy-policy/">privacy policy</a>. This does not subscribe me to marketing emails.</span></label>{key?<><Script id="turnstile-script" src="https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit" strategy="afterInteractive" onReady={mountWidget}/><div ref={widget}/></>:null}{error?<p className="form-error" role="alert">{error}</p>:null}<button className="button" disabled={status==='sending'} type="submit">{status==='sending'?<>Sending<LoaderCircle className="spin" size={18}/></>:<>{booking?'Request this call':'Let’s start the conversation'}<ArrowUpRight size={18}/></>}</button><p className="form-note">{booking?'We’ll reply to confirm. No calendar reservation is made automatically.':'A conversation first. A clear scope and quote next.'}</p></form>;
}
